{
  "name": "coding-kit",
  "description": "Fixes failing tests in the project it is installed into: workspace tools with rewind, an allow-listed shell, permission rules, a loop guard and a read-only explorer",
  "model": "openrouter/openai/gpt-4o-mini",
  "maxSteps": 20,
  "permissionMode": "default",
  "permissions": [
    { "tool": "shell", "when": { "command": "\\brm\\b" }, "action": "deny", "reason": "Deleting files is not allowed" },
    { "tool": ["read_file", "list_dir", "glob", "grep", "load_skill", "task", "delegate_to_explorer", "shell"], "action": "allow" },
    { "tool": ["write_file", "edit_file"], "action": "ask" }
  ],
  "hooks": "hooks.ts",
  "approve": "approve.ts",
  "compaction": { "thresholdPercent": 0.8 },
  "limits": { "maxCostUsd": 0.05 }
}

import type { ApproveToolCall } from '@lousho/build-ai-agent';

/**
 * The kit's approver (pointed at by `agent.json`'s `approve`): the agent asks
 * before every `write_file` / `edit_file`; the approver allows them all except
 * test files, so the model can fix the code but never the tests that judge it.
 */
const approve: ApproveToolCall = ({ args }) => !String(args.path ?? '').endsWith('.test.js');

export default approve;

import type { AgentHook, Message } from '@lousho/build-ai-agent';

/**
 * The kit's hooks (pointed at by `agent.json`'s `hooks`): a loop guard that
 * denies a tool call the model already made twice with the same arguments,
 * then an output cap that keeps long tool results from flooding the context.
 * Ported from examples/coding-harness/index.ts.
 */

/** Test runs are expected to repeat (before and after every change), so the loop guard lets them through. */
const TEST_COMMAND = /^\s*node --test\b/;

/**
 * Deny a tool call the model already made `maxRepeats` times with the same
 * arguments in the same run. Counts are kept per run (keyed by the run's
 * message list), so separate runs and separately loaded agents never share
 * them; test commands and the post-approval re-fire of a paused call are not
 * counted.
 */
export function loopGuard(maxRepeats = 2): AgentHook {
  const runs = new WeakMap<Message[], Map<string, number>>();
  return {
    name: 'loop-guard',
    preToolCall(ctx) {
      if (ctx.resumedAfterApproval) return undefined;
      if (ctx.toolName === 'shell' && TEST_COMMAND.test(String(ctx.args.command ?? ''))) return undefined;
      let seen = runs.get(ctx.messages);
      if (!seen) runs.set(ctx.messages, (seen = new Map()));
      const key = `${ctx.toolName}:${JSON.stringify(ctx.args)}`;
      const count = (seen.get(key) ?? 0) + 1;
      seen.set(key, count);
      if (count > maxRepeats) {
        return { deny: `You already called ${ctx.toolName} with these arguments ${maxRepeats} times. Try something else.` };
      }
      return undefined;
    },
  };
}

/** Cut long tool results so they do not flood the context. */
export function outputCap(maxChars = 4_000): AgentHook {
  return {
    name: 'output-cap',
    postToolCall(_ctx, result) {
      const text = typeof result.result === 'string' ? result.result : JSON.stringify(result.result ?? '');
      if (text.length <= maxChars) return undefined;
      return { result: `${text.slice(0, maxChars)}\n[output cut at ${maxChars} of ${text.length} chars]` };
    },
  };
}

export default [loopGuard(), outputCap()];

{
  "description": "Reads the project and reports where a problem is. Cannot change files.",
  "maxSteps": 6
}

/**
 * The explorer's read-only file tools, bound to the same workspace as the
 * lead's (the agent directory, three levels up from this file): `read_file`,
 * `list_dir`, `glob` and `grep`, with no `write_file` / `edit_file`, so a
 * delegated reading task cannot change anything.
 */
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createFsTools, NodeWorkspace } from '@lousho/build-ai-agent';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const workspace = new NodeWorkspace({ root });
const readOnly = createFsTools(workspace).filter((tool) => ['read_file', 'list_dir', 'glob', 'grep'].includes(tool.name));

export default readOnly;

/**
 * The kit's workspace tools: every file tool and a shell limited to an allow
 * list. The workspace is the agent directory itself - the kit works on the
 * project it is installed into, and `lousho build` bundles this file next to
 * the agent so the built server's workspace is the bundled directory.
 *
 * Because the agent's own files share that directory, the file tools refuse
 * to change them: `agent.*`, `approve.*`, `hooks.*`, `instructions*`,
 * `lousho-registry.json`, and everything under `.lousho/`, `tools/`,
 * `skills/`, `subagents/`, `.git/` and `node_modules/`. Without this the
 * model could rewrite its own approver or permissions.
 *
 * `checkpoints` backs up every write and edit (to `.lousho/checkpoints/` in
 * the workspace, so a rewind still works after a restart); `workspace`,
 * `checkpoints` and `fs` are also exported for code that wants the same
 * objects (a test, or another tool file).
 */
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  createFsTools,
  createShellTool,
  FileWorkspaceCheckpointStore,
  NodeWorkspace,
  normalizeWorkspacePath,
  WorkspaceCheckpoints,
  WorkspaceError,
  type FsProvider,
} from '@lousho/build-ai-agent';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export const workspace = new NodeWorkspace({ root });
export const checkpoints = new WorkspaceCheckpoints(workspace, {
  store: new FileWorkspaceCheckpointStore(path.join(root, '.lousho', 'checkpoints')),
});

const PROTECTED_DIRS = new Set(['.lousho', 'tools', 'skills', 'subagents', 'instructions', '.git', 'node_modules']);
const PROTECTED_ROOT_FILE = /^(agent|approve|hooks)(\..*)?$|^instructions|^lousho-registry\.json$/;

/** True when `p` names one of the agent's own files (case-insensitive; Windows aliases included). */
export function isAgentFile(p: string): boolean {
  // Windows drops trailing dots and spaces, and `APPROV~1.TS` may alias `approve.ts`.
  const segments = normalizeWorkspacePath(p)
    .split('/')
    .map((s) => s.replace(/[. ]+$/, '').toLowerCase());
  if (segments.some((s) => /~\d/.test(s))) return true;
  if (PROTECTED_DIRS.has(segments[0])) return true;
  return segments.length === 1 && PROTECTED_ROOT_FILE.test(segments[0]);
}

function guard(p: string): void {
  if (isAgentFile(p)) {
    throw new WorkspaceError(`${p} is part of the agent's own configuration and cannot be changed. Change the project's code instead.`);
  }
}

/** The workspace as the file tools see it: reads pass through, writes to the agent's own files are refused. */
const projectFiles: FsProvider = {
  readFile: (p) => workspace.readFile(p),
  stat: (p) => workspace.stat(p),
  readdir: (p) => workspace.readdir(p),
  getMode: (p) => workspace.getMode(p),
  async writeFile(p, content) {
    guard(p);
    return workspace.writeFile(p, content);
  },
  async mkdir(p) {
    guard(p);
    return workspace.mkdir(p);
  },
  async rm(p, options) {
    guard(p);
    return workspace.rm(p, options);
  },
  async chmod(p, mode) {
    guard(p);
    return workspace.chmod(p, mode);
  },
};

export const fs = createFsTools(projectFiles, { checkpoints });

/**
 * A shell that only runs the commands a coding harness needs. `node --test`
 * takes test file paths but no flags (a flag such as
 * `--test-reporter-destination=../x` writes outside the project); `git diff`
 * is left out because `git diff --output=<file>` writes anywhere.
 */
export const shell = createShellTool(workspace, {
  needsApproval: false,
  allow: [/^node --test( (?!-)(?![^ ]*\.\.)[\w./-]+)*$/, /^git status( (-s|--short|--porcelain))?$/],
});

export default fs;
